static void test_fan_obd_copies_obd_command_at_speed_99(void)
{
    FAN_DATA_BLOCK_s *db;
    DCDC_DATA_BLOCK_s *dcdc_ptr;
    COOLER_COMPRESSOR_DATA_BLOCK_s *cooler_compressor_ptr;
    boolean_t ret;

    fan_init();
    db = fan_get();
    db->manage.obd_fan_command = fan_command_low;
    db->command.fan_command = fan_command_off;

    dcdc_ptr = dcdc_get();
    dcdc_ptr->manage.dcdc_ready_to_work = TRUE;
    cooler_compressor_ptr = cooler_compressor_get();
    cooler_compressor_ptr->status.speed_of_cooler_compressor_feedback = 99U;

    ret = fan_obd();

    TEST_ASSERT_TRUE(ret);
    TEST_ASSERT_TRUE(db->manage.obd_fan_command_condition);
    TEST_ASSERT_EQUAL(fan_command_low, db->command.fan_command);
}

