static void test_fan_obd_recovers_after_dcdc_ready_transition(void)
{
    FAN_DATA_BLOCK_s *db;
    DCDC_DATA_BLOCK_s *dcdc_ptr;
    COOLER_COMPRESSOR_DATA_BLOCK_s *cooler_compressor_ptr;
    boolean_t ret;

    fan_init();
    db = fan_get();
    db->command.fan_command = fan_command_high;
    db->manage.obd_fan_command_condition = TRUE;
    db->manage.obd_fan_command = fan_command_low;

    dcdc_ptr = dcdc_get();
    cooler_compressor_ptr = cooler_compressor_get();

    dcdc_ptr->manage.dcdc_ready_to_work = FALSE;
    ret = fan_obd();
    TEST_ASSERT_TRUE(ret);
    TEST_ASSERT_EQUAL(fan_command_high, db->command.fan_command);
    TEST_ASSERT_FALSE(db->manage.obd_fan_command_condition);

    dcdc_ptr->manage.dcdc_ready_to_work = TRUE;
    cooler_compressor_ptr->status.speed_of_cooler_compressor_feedback = 100U;
    ret = fan_obd();
    TEST_ASSERT_TRUE(ret);
    TEST_ASSERT_TRUE(db->manage.obd_fan_command_condition);
    TEST_ASSERT_EQUAL(fan_command_low, db->command.fan_command);
}

static void test_fan_obd_alternates_across_speed_boundary(void)
{
    FAN_DATA_BLOCK_s *db;
    DCDC_DATA_BLOCK_s *dcdc_ptr;
    COOLER_COMPRESSOR_DATA_BLOCK_s *cooler_compressor_ptr;

    fan_init();
    db = fan_get();
    db->manage.obd_fan_command = fan_command_off;
    db->manage.obd_fan_command_condition = FALSE;

    dcdc_ptr = dcdc_get();
    dcdc_ptr->manage.dcdc_ready_to_work = TRUE;
    cooler_compressor_ptr = cooler_compressor_get();

    cooler_compressor_ptr->status.speed_of_cooler_compressor_feedback = 101U;
    (void)fan_obd();
    TEST_ASSERT_EQUAL(fan_command_high, db->command.fan_command);
    TEST_ASSERT_FALSE(db->manage.obd_fan_command_condition);

    cooler_compressor_ptr->status.speed_of_cooler_compressor_feedback = 100U;
    (void)fan_obd();
    TEST_ASSERT_EQUAL(fan_command_off, db->command.fan_command);
    TEST_ASSERT_TRUE(db->manage.obd_fan_command_condition);

    cooler_compressor_ptr->status.speed_of_cooler_compressor_feedback = 101U;
    (void)fan_obd();
    TEST_ASSERT_EQUAL(fan_command_high, db->command.fan_command);
    TEST_ASSERT_TRUE(db->manage.obd_fan_command_condition);
}

