void fan_unity_test(void)
{
    /* Initialization, configuration, and getter */
    RUN_TEST(test_fan_init_sets_assigned_fields_to_defaults);
    RUN_TEST(test_fan_init_preserves_obd_nrc_field);
    RUN_TEST(test_fan_cfg_sets_command_and_obd_fan_command_off);
    RUN_TEST(test_fan_cfg_preserves_non_target_fields);

    /* Normal command selection */
    RUN_TEST(test_fan_command_sets_high_when_ready_and_manage_high);
    RUN_TEST(test_fan_command_sets_low_when_ready_and_manage_low);
    RUN_TEST(test_fan_command_sets_off_when_ready_and_manage_off);
    RUN_TEST(test_fan_command_maps_invalid_manage_command_to_off);
    RUN_TEST(test_fan_command_sets_off_when_dcdc_not_ready);
    RUN_TEST(test_fan_command_overwrites_output_on_repeated_calls);

    /* OBD override and external dependencies */
    RUN_TEST(test_fan_obd_copies_obd_command_at_speed_99);
    RUN_TEST(test_fan_obd_copies_obd_command_at_speed_100);
    RUN_TEST(test_fan_obd_forces_high_at_speed_101);
    RUN_TEST(test_fan_obd_copies_obd_command_at_speed_10000);
    RUN_TEST(test_fan_obd_copies_obd_command_at_speed_10001);
    RUN_TEST(test_fan_obd_falls_back_for_uint16_extremes);
    RUN_TEST(test_fan_obd_passes_through_invalid_obd_command);
    RUN_TEST(test_fan_obd_preserves_command_when_dcdc_not_ready);
    RUN_TEST(test_fan_obd_recovers_after_dcdc_ready_transition);
    RUN_TEST(test_fan_obd_alternates_across_speed_boundary);
    RUN_TEST(test_fan_obd_uses_external_dcdc_ready_not_cached);
}
